// js
// 労働基準法 art.39(1)–(2): a grant day six months after hire and each year after it, the days by length of service.
const employment = ctx.subject.employment;
const started = get(employment, 'service_started_on', get(employment, 'effective_range.from', null));
const offset = ctx.lookup.service_offset_months;
const months = calendar_completed_months(started, ctx.as_of);
if (months < offset) return 0;
const years = Math.floor((months - offset) / 12);
const grant = add_months(started, offset + years * 12);
const extension = get(employment, 'employee_extension_data', {});
// art.39(1)–(2): attendance below the ratio before a grant day leaves that year without a grant; HR records it on the day.
if (get(extension, 'events', []).some((event) => event.kind === 'ATTENDANCE_BELOW_RATIO' && event.on === grant)) return 0;
// art.39(3) with 施行規則 art.24の3: below the weekly hours and the weekly or yearly days, the table for the days scheduled.
const terms = get(employment, 'terms', {});
const hours = Number(get(terms, 'normal_hours_per_week', 0));
const perYear = get(extension, 'normal_days_per_year', null);
const yearly = perYear == null ? null : ctx.lookup.grant_days_by_normal_days_per_year.filter((row) => row.normal_days_per_year <= perYear).at(-1);
const perWeek = perYear == null ? Number(get(terms, 'normal_days_per_week', ctx.lookup.full_time_days_per_week)) : get(yearly ?? {}, 'days', 0);
const full = perYear == null ? perWeek >= ctx.lookup.full_time_days_per_week : perYear >= ctx.lookup.full_time_days_per_year;
if (hours > 0 && hours < ctx.lookup.full_time_weekly_hours && !full) {
	const row = ctx.lookup.grant_days_by_normal_days_per_week.filter((item) => item.normal_days_per_week === perWeek && item.service_year <= years + 1).at(-1);
	return get(row ?? {}, 'days', 0);
}
return ctx.lookup.service_bands.filter((band) => band.service_months <= months).reduce((days, band) => Math.max(days, band.days), 0);

